  "logger_middleware.ts": "import type { MiddlewareArgs } from \"dashi\";\n\nexport async function logger({ ctx, next }: MiddlewareArgs): Promise<Response> {\n  const start = performance.now();\n  console.log(ctx.req.method, ctx.url.pathname);\n  const res = await next();\n  const ms = Math.round(performance.now() - start);\n  console.log(ctx.req.method, ctx.url.pathname, res.status, `${ms}ms`);\n  return res;\n}\n",
  "main.ts": "import { CacheStrategy, serve, staticFile } from \"dashi\";\nimport { error, fatal, notFound } from \"./errors.tsx\";\nimport { Home } from \"./home/mod.tsx\";\nimport { logger } from \"./logger_middleware.ts\";\nimport { RootLayout } from \"./root_layout.tsx\";\n\nif (import.meta.main) {\n  const port = Deno.env.get(\"PORT\");\n  serve(({ route }) => ({\n    layouts: [RootLayout],\n    middleware: [logger],\n    notFound,\n    error,\n    routes: [\n      route(\"/\", { GET: Home }),\n      route(\"/generated/:file\", {\n        GET: ({ ctx }) =>\n          staticFile(ctx, `${import.meta.dirname}/generated`, ctx.params.file, {\n            strategy: CacheStrategy.Immutable,\n          }),\n      }),\n      route(\"/static/:file\", {\n        GET: ({ ctx }) =>\n          staticFile(ctx, `${import.meta.dirname}/static`, ctx.params.file, {\n            strategy: CacheStrategy.Immutable,\n          }),\n      }),\n    ],\n  }), {\n    fatal,\n    ...(port === undefined ? {} : { port: Number(port) }),\n  });\n}\n",
